#!/usr/bin/env node
import { spawn } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync, createWriteStream } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { ROOT, sourceDigest, sha256, evaluationDigest } from './evidence.mjs';
import { menuVisitSchedule, REQUIRED_NATIVE_CHECKS } from './e2e.mjs';
import { CONFIG } from './config.mjs';
export const COMBINATIONS = [...CONFIG.native.shortMinutes.flatMap(minutes=>CONFIG.native.profiles.map(profile=>({minutes,profile}))),
  {minutes:CONFIG.native.longJourney.minutes,profile:CONFIG.native.longJourney.profile}];
const check=(ok,message)=>{if(!ok)throw Error(message);};
const json=value=>JSON.stringify(value,null,2)+'\n';
const read=path=>JSON.parse(readFileSync(path,'utf8'));
const atomic=(path,value)=>{writeFileSync(path+'.tmp',json(value));renameSync(path+'.tmp',path);};
const finite=value=>typeof value==='number'&&Number.isFinite(value);
const object=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
export function completedNativeRun(run, exitCode, key) {
  const session=run?.sessions?.[0];
  return exitCode===0&&run?.completion==='completed'&&run.status==='passed'&&run.sessions.length===1&&
    session?.completion==='completed'&&`${session.minutes}-${session.profile}`===key&&
    finite(session.elapsedMs)&&session.elapsedMs>=session.minutes*60_000&&
    COMBINATIONS.some(c=>c.minutes===session.minutes&&c.profile===session.profile);
}
/** Resume only complete combinations. Interrupted originals remain immutable attempts. */
export function resumableRuns(records, digest, toolDigest, readFile=readFileSync) {
  const runs=[],retry=[];
  for(const record of records) {
    const bytes=readFile(record.path);check(sha256(bytes)===record.sha256,'Existing result changed');
    const run=JSON.parse(bytes.toString());
    check(run.sourceDigest===digest&&run.evaluationDigest===toolDigest,'Existing result stale');
    if(completedNativeRun(run,record.exitCode,record.key))runs.push(record);
    else retry.push({...record,recovery:'Incomplete original preserved; rerun only this combination',completion:run.completion??'unknown'});
  }
